//! 🧪️ Shared malformed rectangles and annotation frames agree with physical source coordinates.
use super::*;
#[test]
fn portable_annotation_geometry_and_rectangle_refusals(){let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧪️fixtures/🔣️.json")).unwrap();let point=|value:&serde_json::Value|[value[0].as_f64().unwrap(),value[1].as_f64().unwrap(),value[2].as_f64().unwrap()];for case in fixture["refusedRectangles"].as_array().unwrap(){let points=case["points"].as_array().unwrap().iter().map(point).collect::<Vec<_>>();assert!(rectangle_bounds(&points,0.0,100.0).is_none());}for case in fixture["annotations"].as_array().unwrap(){let p=point(&case["position"]);let x=point(&case["xAxis"]);let y=point(&case["yAxis"]);let w=case["width"].as_f64().unwrap();let h=case["height"].as_f64().unwrap();let min=case["minX"].as_f64().unwrap();let max=case["maxY"].as_f64().unwrap();let bounds=annotation_bounds(p,x,y,w,h,min,max);let actual=outline(&bounds,max);for(dx,dy)in[(0.0,0.0),(w,0.0),(w,h),(0.0,h)]{let expected=[(p[0]+x[0]*dx+y[0]*dy-min)*MM,(p[1]+x[1]*dx+y[1]*dy)*MM,0.0];assert!(actual.iter().any(|point|point.iter().zip(expected).all(|(a,b)|(a-b).abs()<1e-9)));}}}
